Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='deployedverbs', at=datetime(2026, 11, 16, 0, 0, 0), actor='assistant', title='A script the deployed binary runs calls only what a deployed release has', body="*A script the deployed binary runs calls only what a deployed release has* (2026-11-16): the gate and the train run the train's `scripts/public-tree.sh` with the deployed binary, so a script that calls a verb or a flag its own pull request adds fails the train. A pull request that adds one lands and deploys first, and a later pull request switches the script.", rationale='The train with #520 was red at its first step: public-tree.sh called instance words, which the deployed 2.1.146 did not have.', supersedes=()))